class Point { x: int = 10; y: int = 20; }
export function test(): int {
  let p: Point = {};
  return p.x + p.y;
}

class Point { x: int = 0; y: int = 0; }
export function test(): int {
  let p: Point = { x: 1, y: 2 };
  return p.x * 10 + p.y;
}

class Point { x: int = 0; y: int = 0; }
export function test(): int {
  let p: Point = { x: 1, y: 2 };
  p.x = p.x + 5;
  p.y = p.y + 2;
  return p.x * 10 + p.y;
}

class Mixed { i: int = 0; n: number = 0.0; b: boolean = false; s: string = ""; }
export function test(): int {
  let m: Mixed = { i: 3, n: 2.5, b: true, s: "jvm" };
  if (m.b === true && m.s === "jvm" && m.i === 3 && m.n > 2.0 && m.n < 3.0) { return m.i + 1; }
  return 0;
}

class Bag { count: int = 0; }
export function test(): int {
  let a: Bag = {};
  let b: Bag = {};
  a.count = 7;
  return a.count + b.count;
}

let origin: Point = {};
class Point { x: int = 1; y: int = 2; }
export function test(): int { return origin.x * 10 + origin.y; }

import * as console from "std/console"
class Pair { a: string = ""; b: string = ""; }
function tag(s: string): string { console.log(s); return s; }
export function test(): int {
  let p: Pair = { b: tag("second"), a: tag("first") };
  if (p.a === "first" && p.b === "second") { return 1; }
  return 0;
}

